-- Koha's patron attribute tables, for fictitious patrons of koha-patrons.sql
-- (docs/specs/circulacao/patron-attributes.md, items 16 to 19).
CREATE TABLE `borrower_attribute_types` (`code` varchar(64) NOT NULL, `description` varchar(255) NOT NULL, `repeatable` tinyint(1) NOT NULL DEFAULT 0, `unique_id` tinyint(1) NOT NULL DEFAULT 0, `is_date` tinyint(1) NOT NULL DEFAULT 0, `opac_display` tinyint(1) NOT NULL DEFAULT 0, `opac_editable` tinyint(1) NOT NULL DEFAULT 0, `staff_searchable` tinyint(1) NOT NULL DEFAULT 0, `searched_by_default` tinyint(1) NOT NULL DEFAULT 0, `authorised_value_category` varchar(32) DEFAULT NULL, `display_checkout` tinyint(1) NOT NULL DEFAULT 0, `category_code` varchar(10) DEFAULT NULL, `class` varchar(255) NOT NULL DEFAULT '', `keep_for_pseudonymization` tinyint(1) NOT NULL DEFAULT 0, `mandatory` tinyint(1) NOT NULL DEFAULT 0, `opac_mandatory` tinyint(1) NOT NULL DEFAULT 0, PRIMARY KEY (`code`));
INSERT INTO `borrower_attribute_types` VALUES ('TURNO','Turno',0,0,0,1,0,1,0,'TURNOS',1,NULL,'',0,0,0),('ESCOLA','Escola',0,1,0,0,0,1,0,NULL,0,'EST','',0,1,0),('FORM','Formatura',0,0,1,0,0,0,0,NULL,0,NULL,'',0,0,0),('VAZIO','Vazio',1,0,0,0,0,0,0,'NADA',0,NULL,'',0,0,0);
CREATE TABLE `borrower_attribute_types_branches` (`bat_code` varchar(64) DEFAULT NULL, `b_branchcode` varchar(10) DEFAULT NULL);
INSERT INTO `borrower_attribute_types_branches` VALUES ('TURNO','CTR');
CREATE TABLE `authorised_values` (`id` int(11) NOT NULL, `category` varchar(32) NOT NULL DEFAULT '', `authorised_value` varchar(80) NOT NULL DEFAULT '', `lib` varchar(200) DEFAULT NULL, `lib_opac` varchar(200) DEFAULT NULL, `imageurl` varchar(200) DEFAULT NULL, PRIMARY KEY (`id`));
INSERT INTO `authorised_values` VALUES (1,'TURNOS','M','Manhã',NULL,NULL),(2,'TURNOS','N','Noite',NULL,NULL),(3,'TURNOS','N2','Noite',NULL,NULL),(4,'LOC','X','Outro',NULL,NULL);
CREATE TABLE `borrower_attributes` (`id` int(11) NOT NULL, `borrowernumber` int(11) NOT NULL, `code` varchar(64) NOT NULL, `attribute` varchar(255) DEFAULT NULL, PRIMARY KEY (`id`));
INSERT INTO `borrower_attributes` VALUES (1,1,'TURNO','M'),(2,1,'TURNO','N'),(3,2,'TURNO','N2'),(4,4,'TURNO','Z'),(5,1,'FORM','2019-12-01'),(6,2,'FORM','ontem'),(7,999,'TURNO','M'),(8,1,'ESCOLA','Escola A'),(9,2,'ESCOLA','Escola A'),(10,1,'SUMIU','x');
CREATE TABLE `currency` (`currency` varchar(10) NOT NULL DEFAULT '', `symbol` varchar(5) DEFAULT NULL, `isocode` varchar(5) DEFAULT NULL, `timestamp` timestamp NOT NULL, `rate` float(15,5) DEFAULT NULL, `active` tinyint(1) DEFAULT NULL, `archived` tinyint(1) DEFAULT 0, `p_sep_by_space` tinyint(1) DEFAULT 0, `p_cs_precedes` tinyint(1) DEFAULT 1, PRIMARY KEY (`currency`));
